-- PLC Intelligence consolidated demonstration seed.
-- 2026-27 Term 1: three subject-specific PLC teams, nine teachers,
-- nine sections, 243 fictional students, four standards/cycles per team,
-- coherent PRE/POST evidence, instructional groups, responses, interventions,
-- commitments, notes, pacing, and all role/access assignments.
-- All people and student records are fictional demonstration data.

