INSERT INTO standards (standard_id, code, description, subject, grade_level) VALUES
    (301, '3.R.5', 'Ask and answer questions to demonstrate understanding of a text, referring explicitly to the text as the basis for the answers. (RL & RI)', 'English Language Arts', 'Grade 3'),
    (302, '3.R.6', 'Read a variety of texts including those from diverse cultures, retell the text according to the text structure including the main idea and how key details support the main idea. (RL & RI)', 'English Language Arts', 'Grade 3'),
    (303, '3.R.7', 'Describe characters in a story and explain how their actions contribute to the sequence of events. (RL) Describe the relationship between a series of historical events, scientific ideas or concepts, or steps in technical procedures in a text, using language that pertains to time, sequence, and cause/effect. (RI)', 'English Language Arts', 'Grade 3'),
    (304, '3.R.8', 'Determine the meaning of words, phrases, similes, metaphors, and academic and content-specific words within a text. (RL & RI)', 'English Language Arts', 'Grade 3'),
    (501, '5.NBT.1', 'Recognize that in a multi-digit number, a digit in one place represents 10 times as much as it represents in the place to its right and 1/10 of what it represents in the place to its left.', 'Mathematics', 'Grade 5'),
    (502, '5.NBT.2', 'Explain patterns in the number of zeros of the product when multiplying a number by powers of 10, and explain patterns in the placement of the decimal point when a decimal is multiplied or divided by a power of 10. Use whole-number exponents to denote powers of 10.', 'Mathematics', 'Grade 5'),
    (503, '5.NBT.5', 'Fluently multiply multi-digit whole numbers using the standard algorithm.', 'Mathematics', 'Grade 5'),
    (504, '5.NBT.6', 'Find whole-number quotients of whole numbers with up to four-digit dividends and two-digit divisors, using strategies based on place value, the properties of operations, and/or the relationship between multiplication and division. Illustrate and explain the calculation by using equations, rectangular arrays, and/or area models.', 'Mathematics', 'Grade 5'),
    (801, 'SCI.8.1.1', 'Develop a model to describe the scale and proportion of atoms and molecules. Emphasize developing atomic models of elements and their numbers of protons, neutrons, and electrons, as well as models of simple molecules. Topics like valence electrons, bond energy, ionic complexes, ions, and isotopes will be introduced at the high school level. (PS1.A)', 'Science', 'Grade 8'),
    (802, 'SCI.8.1.2', 'Obtain information about various properties of matter, evaluate how different materials’ properties allow them to be used for particular functions in society, and communicate your findings. Emphasize general properties of matter. Examples could include color, density, flammability, hardness, malleability, odor, ability to rust, solubility, state, or the ability to react with water. (PS1.A)', 'Science', 'Grade 8'),
    (803, 'SCI.8.1.3', 'Plan and conduct an investigation and then analyze and interpret the data to identify patterns in changes in a substance’s properties to determine whether a chemical reaction has occurred. Examples could include changes in properties such as color, density, flammability, odor, solubility, or state. (PS1.A, PS1.B)', 'Science', 'Grade 8'),
    (804, 'SCI.8.1.5', 'Develop a model that uses computational thinking to illustrate cause and effect relationships in particle motion, temperature, density, and state of a pure substance when heat energy is added or removed. Emphasize molecular-level models of solids, liquids, and gases to show how adding or removing heat energy can result in phase changes, and focus on calculating the density of a substance’s state. (PS3.A)', 'Science', 'Grade 8');

INSERT INTO standard_core_ideas (core_idea_id, standard_id, name, description, sort_order) VALUES
    (3011, 301, 'Question Formation', 'Ask relevant questions before, during, and after reading.', 1),
    (3012, 301, 'Explicit Text Evidence', 'Locate and cite details that directly support an answer.', 2),
    (3013, 301, 'Complete Response', 'Connect the answer and evidence in a clear explanation.', 3),
    (3021, 302, 'Main Idea', 'State what the text is mostly about.', 1),
    (3022, 302, 'Supporting Details', 'Select details that directly support the main idea.', 2),
    (3023, 302, 'Structured Retell', 'Retell the text in an order that reflects its structure.', 3),
    (3031, 303, 'Sequence', 'Identify and describe the order of events, ideas, or steps.', 1),
    (3032, 303, 'Cause and Effect', 'Explain how one action or idea affects another.', 2),
    (3033, 303, 'Relationship Evidence', 'Use text details to explain relationships.', 3),
    (3041, 304, 'Context Clues', 'Use nearby words and sentences to infer meaning.', 1),
    (3042, 304, 'Figurative Language', 'Interpret grade-level similes and metaphors.', 2),
    (3043, 304, 'Academic Vocabulary', 'Determine and apply content-specific word meanings.', 3),
    (5011, 501, 'Ten-Times Relationship', 'Explain movement one place to the left as ten times the value.', 1),
    (5012, 501, 'One-Tenth Relationship', 'Explain movement one place to the right as one tenth the value.', 2),
    (5013, 501, 'Place Value Reasoning', 'Use equations, models, and words to justify place-value relationships.', 3),
    (5021, 502, 'Powers of Ten', 'Represent powers of ten using whole-number exponents.', 1),
    (5022, 502, 'Decimal Patterns', 'Explain decimal-place patterns when multiplying or dividing by powers of ten.', 2),
    (5023, 502, 'Pattern Generalization', 'State and justify a general rule from numerical patterns.', 3),
    (5031, 503, 'Place Value and Partial Products', 'Connect each partial product to its place value.', 1),
    (5032, 503, 'Standard Algorithm', 'Accurately apply and record the standard multiplication algorithm.', 2),
    (5033, 503, 'Reasonableness and Error Analysis', 'Estimate, check, and explain multiplication errors.', 3),
    (5041, 504, 'Quotient Estimation', 'Use compatible numbers and place value to estimate a quotient.', 1),
    (5042, 504, 'Division Strategies', 'Use equations, partial quotients, arrays, or area models.', 2),
    (5043, 504, 'Explain and Check', 'Explain the strategy and verify with multiplication.', 3),
    (8011, 801, 'Subatomic Particles', 'Relate protons, neutrons, and electrons to an atomic model.', 1),
    (8012, 801, 'Scale and Proportion', 'Describe relative scale within atoms and molecules.', 2),
    (8013, 801, 'Model Construction', 'Build and revise models of atoms and simple molecules.', 3),
    (8021, 802, 'Matter Properties', 'Identify and distinguish relevant physical and chemical properties.', 1),
    (8022, 802, 'Property-Function Match', 'Evaluate how properties make a material suitable for a function.', 2),
    (8023, 802, 'Evidence Communication', 'Communicate a material recommendation using evidence.', 3),
    (8031, 803, 'Investigation Design', 'Plan a fair investigation that produces useful evidence.', 1),
    (8032, 803, 'Data Pattern Analysis', 'Analyze patterns in measured property changes.', 2),
    (8033, 803, 'Reaction Evidence', 'Use multiple observations to support a reaction claim.', 3),
    (8041, 804, 'Particle Motion', 'Model particle motion in solids, liquids, and gases.', 1),
    (8042, 804, 'Heat and Phase Change', 'Explain cause-and-effect relationships among heat, motion, and state.', 2),
    (8043, 804, 'Density Reasoning', 'Calculate and interpret density across states of matter.', 3);

